  function setMaternityDoctor(id){const floor=state.floors[activeRoomIndex],person=residentById(id),selected=floor.workerIds.includes(id);if(selected)floor.workerIds=[];else{if(!person||person.age<=16||person.sick||!meetsWorkerSkill(person,floor))return toast('助产医生需要服务至少 3 且科研达到 5');removePersonAssignments(id,floor);floor.workerIds=[id]}save();render();openMaternity(activeRoomIndex);toast(selected?'助产医生已离岗':`${person.name} 成为助产医生`)}
