  const renderWorkerRoom=openRoom;openRoom=function(index){renderWorkerRoom(index);const floor=state.floors[index];if(floor?.type!=='clothing')return;const reserveOptions=[0,1,2,3,5,10],people=eligibleFirst(state.people,person=>!person.hasClothes);$('workerOptions').insertAdjacentHTML('beforeend',`<div class="school-section clothing-settings"><h3>分配模式</h3><small>店内保留指定数量，超过的衣服自动按 €50/件出售。</small><div class="skill-choices">${reserveOptions.map(value=>`<button class="${floor.clothingReserve===value?'selected':''}" data-clothing-reserve="${value}">预留 ${value}</button>`).join('')}</div></div><div class="school-section"><h3>居民领取 · 当前库存 ${floor.clothingStock}</h3>${people.map(person=>`<button class="worker-option ${person.hasClothes?'compact-ineligible':''}" data-claim-clothing="${person.id}" ${person.hasClothes||floor.clothingStock<=0?'disabled':''}><span class="worker-mini" style="background-position:${spritePosition(person.sprite)}"></span><span><strong>${person.name}</strong><small>${person.hasClothes?'已有衣服 · 永久满意度＋10':'领取 1 件衣服并永久增加 10 满意度'}</small></span><em>${person.hasClothes?'已领取':'领取'}</em></button>`).join('')}</div>`);document.querySelectorAll('[data-clothing-reserve]').forEach(button=>button.onclick=()=>setClothingReserve(Number(button.dataset.clothingReserve)));document.querySelectorAll('[data-claim-clothing]').forEach(button=>button.onclick=()=>claimClothing(button.dataset.claimClothing))}
  function setClothingReserve(value){const floor=state.floors[activeRoomIndex];if(floor?.type!=='clothing')return;floor.clothingReserve=Math.max(0,value);const sold=Math.max(0,floor.clothingStock-floor.clothingReserve);if(sold){floor.clothingStock-=sold;state.money+=sold*50}save();render();openRoom(activeRoomIndex);toast(sold?`预留已更新，售出 ${sold} 件衣服，收入 ${euro(sold*50)}`:`服装店预留数量改为 ${floor.clothingReserve}`)}
